const steps = Array.from(document.querySelectorAll('nys-step'));
const stepContent = document.getElementById('step-content');
const nextButton = document.getElementById('next-step');

function advanceStep() {
  const currentIndex = steps.findIndex((step) => step.hasAttribute('current'));
  if (currentIndex === -1 || currentIndex === steps.length - 1) return;

  steps[currentIndex].removeAttribute('current');
  steps[currentIndex].setAttribute('previous', '');
  steps[currentIndex + 1].setAttribute('current', '');
  steps[currentIndex + 1].setAttribute('selected', '');

  const label = steps[currentIndex + 1].getAttribute('label');
  stepContent.textContent = `You are on step ${currentIndex + 2} of ${steps.length}: ${label}.`;

  if (currentIndex + 1 === steps.length - 1) {
    nextButton.disabled = true;
  }
}

nextButton.addEventListener('nys-click', advanceStep);
